CREATE POLICY product_photo_store_boundary ON storage.objects AS RESTRICTIVE FOR ALL TO authenticated USING(bucket_id <> 'product-images' OR (split_part(name,'/',1)=public.current_store_id()::text) OR (position('/' in name)=0 AND EXISTS(SELECT 1 FROM public.stores WHERE id=public.current_store_id() AND is_vendor_store))) WITH CHECK(bucket_id <> 'product-images' OR split_part(name,'/',1)=public.current_store_id()::text);